+// API keys and role-based access control: viewer < cook < manager.
+import { timingSafeEqual } from "node:crypto";
+import { AppError } from "../errors.js";
+
+/** Ordered roles, from least to most privileged. */
+export const ROLES = ["viewer", "cook", "manager"];
+
+function keyEquals(a, b) {
+  const bufA = Buffer.from(a);
+  const bufB = Buffer.from(b);
+  return bufA.length === bufB.length && timingSafeEqual(bufA, bufB);
+}
+
+/** Finds an API key by secret, or throws AppError unauthorized. */
+export function authenticate(store, key) {
+  if (typeof key !== "string" || !key) throw new AppError("unauthorized");
+  const entry = (store.data.apiKeys ?? []).find((k) => typeof k.key === "string" && keyEquals(k.key, key));
+  if (!entry) throw new AppError("unauthorized");
+  return entry;
+}
+
+/** Checks that `apiKey` has at least `minRole`, or throws AppError forbidden. */
+export function authorize(apiKey, minRole) {
+  const actual = ROLES.indexOf(apiKey?.role);
+  const required = ROLES.indexOf(minRole);
+  if (actual < 0 || required < 0 || actual < required) throw new AppError("forbidden");
+}
